import boto3

def summarize_message_processing_results(topic_arn, message_id):
    sns_client = boto3.client('sns')
    response = sns_client.get_message_attributes(
        TopicArn=topic_arn,
        MessageId=message_id
    )
    attributes = response['MessageAttributes']
    summary = {
        'message_id': message_id,
        'attributes': attributes
    }
    return summary

from google.cloud import pubsub_v1


class PubSubRequest:
    def __init__(self, topic_name, message):
        self.topic_name = topic_name
        self.message = message

    def publish(self, project_id):
        publisher = pubsub_v1.PublisherClient()
        topic_path = publisher.topic_path(project_id, self.topic_name)
        data = self.message.encode('utf-8')
        future = publisher.publish(topic_path, data)
        print(f'Published message ID: {future.result()}')


class PubSubResponse:
    def __init__(self, message):
        self.message = message

    def deserialize(self):
        return self.message.data.decode('utf-8')


def normalize_message(message):
    return message.lower()

import boto3

def publish_batch(topic_arn, messages):
    sns_client = boto3.client('sns')
    publish_batch_request_entries = []
    for message in messages:
        publish_batch_request_entries.append({
            'Id': message['Id'],
            'Message': message['Message']
        })
    response = sns_client.publish_batch(
        TopicArn=topic_arn,
        PublishBatchRequestEntries=publish_batch_request_entries
    )
    return response

if __name__ == '__main__'):
    topic_arn = 'arn:aws:sns:us-east-1:123456789012:my-topic'
